1	import java.util.List;
2	/**
3	 * A class representing shared characteristics of animals.
4	 *
5	 * @version 25/02/2022
6	 */
7	public abstract class Animal extends LivingOrganism
8	{
9	    // Default disease probabilities shared by all species.
10	    private static final double DISEASE_PROBABILITY         = 0.00000015;
11	    private static final double DISEASE_SPREAD_PROBABILITY  = 0.80;
12	    private static final double INFECTION_DEATH_PROBABILITY = 0.13;
13	    private static final double IMMUNE_PROBABILITY          = 0.05;
14	
15	    /**
16	     * Immutable value object holding the species-specific parameters that
17	     * every animal subclass must supply. Stored as a static constant per
18	     * species and applied via {@link #applyConfig(SpeciesConfig)}.
19	     */
20	    protected static class SpeciesConfig {
21	        final int breedingAge;
22	        final int maxAge;
23	        final double breedingProbability;
24	        final int maxLitterSize;
25	        final int maxFoodLevel;
26	        final int foodValue;
27	
28	        SpeciesConfig(int breedingAge, int maxAge, double breedingProbability,
29	                      int maxLitterSize, int maxFoodLevel, int foodValue) {
30	            this.breedingAge = breedingAge;
31	            this.maxAge = maxAge;
32	            this.breedingProbability = breedingProbability;
33	            this.maxLitterSize = maxLitterSize;
34	            this.maxFoodLevel = maxFoodLevel;
35	            this.foodValue = foodValue;
36	        }
37	    }
38	
39	    // Indicates whether an animal is a female or not;
40	    protected boolean isFemale;
41	    // The age at which an animal can start to breed.
42	    protected int breedingAge;
43	    // The age to which an animal can live.
44	    protected int maxAge;
45	    // The likelihood of an animal breeding.
46	    protected double breedingProbability;
47	    // Whether the animal is infected or not
48	    protected boolean infected;
49	    // The likelihood of an animal having a disease.
50	    protected double diseaseProbability;
51	    // The likelihood of an animal catching a disease from another animal
52	    protected double diseaseSpreadProbability;
53	    // The likelihood of an animal dying from catching the disease
54	    protected double deathFromInfectionProbability;
55	    // The likelihood of an animal becoming immune to the disease
56	    protected double immuneProbability;
57	    // whether the animal is immune or not
58	    protected boolean immune;
59	    // The maximum number of births.
60	    protected int maxLitterSize;
61	    // The animals's age.
62	    protected int age;
63	    // The animals's food level, which is increased by eating prey.
64	    protected int foodLevel;
65	    // The maximum food level that an animal will eat at. The food level they will stop
66	    // being hungry at
67	    protected int maxFoodLevel;
68	    // Probability that an animal will move at a given step.
69	    protected double movementProbability;
70	    
71	    /**
72	     * Create a new animal at location in field.
73	     * 
74	     * @param field The field currently occupied.
75	     * @param location The location within the field.
76	     * @param infected Initial state if the animal is infected or not
77	     * @param immune   Initial state if the animal is immune or not
78	     */
79	    public Animal(Field field, Location location, boolean infected, boolean immune)
80	    {
81	        super(field, location);
82	        alive = true;
83	        this.infected = infected;
84	        this.immune = immune;
85	        
86	        diseaseProbability = DISEASE_PROBABILITY;
87	        diseaseSpreadProbability = DISEASE_SPREAD_PROBABILITY;
88	        deathFromInfectionProbability = INFECTION_DEATH_PROBABILITY;
89	        immuneProbability = IMMUNE_PROBABILITY;
90	        
91	        isFemale = rand.nextBoolean();
92	    }
93	    
94	    /**
95	     * @Override
96	     *
97	     * Make this animal act - that is: make it do
98	     * whatever it wants/needs to do.
99	     *
100	     * @param newAnimals A list to receive newly born animals.
101	     */
102	    public void act(List<LivingOrganism> newAnimals)
103	    {
104	        incrementAge();
105	        incrementHunger();
106	        updateDiseaseState();
107	
108	        if(isAlive())
109	        {
110	            tryContractDisease();
111	
112	            if(isFemale && canBreed() && rand.nextDouble() <= breedingProbability)
113	            {
114	                populate(newAnimals);
115	            }
116	
117	            tryMove();
118	        }
119	    }
120	
121	    /**
122	     * Progress the animal's disease/immunity status by one step:
123	     * an infected animal may die or recover; an immune animal may lose immunity.
124	     */
125	    private void updateDiseaseState()
126	    {
127	        if(!immune && infected)
128	        {
129	            if(rand.nextDouble() <= deathFromInfectionProbability)
130	            {
131	                setDead();
132	            }
133	            else if(rand.nextDouble() <= immuneProbability)
134	            {
135	                immune = true;
136	                infected = false;
137	            }
138	        }
139	        else if(rand.nextDouble() <= immuneProbability / 15)
140	        {
141	            // Non-infected animals slowly lose immunity over time
142	            immune = false;
143	        }
144	    }
145	
146	    /**
147	     * Attempt to infect a susceptible (non-immune, non-infected) animal,
148	     * either via a neighbouring infected animal or spontaneously.
149	     */
150	    private void tryContractDisease()
151	    {
152	        if(immune || infected)
153	        {
154	            return;
155	        }
156	        if(surroundingsInfected() && rand.nextDouble() <= diseaseSpreadProbability)
157	        {
158	            infected = true;
159	        }
160	        else if(rand.nextDouble() <= diseaseProbability)
161	        {
162	            infected = true;
163	        }
164	    }
165	
166	    /**
167	     * Attempt to move: first towards food, then to any free adjacent cell.
168	     * Dies from overcrowding if no adjacent cell is free.
169	     */
170	    private void tryMove()
171	    {
172	        Location newLocation = findFood();
173	
174	        if(newLocation == null)
175	        {
176	            Location freeLocation = getField().freeAdjacentLocation(getLocation(), Animal.class);
177	
178	            if(freeLocation == null && rand.nextDouble() < 0.3)
179	            {
180	                setDead();
181	            }
182	
183	            if(rand.nextDouble() <= movementProbability)
184	            {
185	                newLocation = freeLocation;
186	            }
187	        }
188	
189	        if(newLocation != null)
190	        {
191	            setLocation(newLocation);
192	        }
193	    }
194	    
195	    /**
196	     * Copy the species-specific parameters from a {@link SpeciesConfig} into
197	     * this animal's instance fields. Call this once in each concrete
198	     * subclass constructor after calling super().
199	     */
200	    protected void applyConfig(SpeciesConfig config) {
201	        breedingAge = config.breedingAge;
202	        maxAge = config.maxAge;
203	        breedingProbability = config.breedingProbability;
204	        maxLitterSize = config.maxLitterSize;
205	        maxFoodLevel = config.maxFoodLevel;
206	        foodValue = config.foodValue;
207	    }
208	
209	    /**
210	     * Look for food adjacent to the current location.
211	     * Only the first live prey or plant is eaten.
212	     *
213	     * @return Where food was found, or null if it wasn't.
214	     */
215	    abstract protected Location findFood();
216	
217	    /**
218	     * Instantiate a new offspring of this species at the given location.
219	     * Each concrete species class overrides this instead of requiring
220	     * {@link #createNewOffspring} to maintain a per-species if-chain.
221	     *
222	     * @param loc      The location for the new animal.
223	     * @param infected Whether the offspring starts infected.
224	     * @param immune   Whether the offspring starts immune.
225	     * @return A new animal of the same species as this one.
226	     */
227	    protected abstract Animal createOffspringAt(Location loc, boolean infected, boolean immune);
228	
229	    /**
230	     * @Override
231	     * 
232	     * Indicate that the animal is no longer alive.
233	     * It is removed from the field.
234	     */
235	    protected void setDead()
236	    {
237	        alive = false;
238	
239	        if(location != null)
240	        {
241	            field.clear(location, Animal.class);
242	            location = null;
243	        }
244	    }
245	    
246	    /**
247	     * @Override
248	     * 
249	     * When called, the animal is killed and returns
250	     * its food value.
251	     * 
252	     * @return The food value of the animal eaten.
253	     */
254	    protected int beEaten() 
255	    {
256	        setDead();
257	        
258	        return foodValue;
259	    }
260	    
261	    /**
262	     * @Override
263	     * 
264	     * Place the animal at the new location in the given field.
265	     * 
266	     * @param newLocation The animal's new location.
267	     */
268	    protected void setLocation(Location newLocation)
269	    {
270	        if(location != null)
271	        {
272	            field.clear(location, Animal.class);
273	        }
274	        location = newLocation;
275	        field.place(this, newLocation);
276	    }
277	    
278	    /**
279	     * Returns the gender of the animal.
280	     * 
281	     * @return Returns true if female.
282	     */
283	    protected boolean getIsFemale() 
284	    {
285	        return isFemale;
286	    }
287	    
288	    /**
289	     * @Override
290	     * 
291	     * Increase the age.
292	     * This could result in the Animal's death.
293	     */
294	    protected void incrementAge()
295	    {
296	        age++;
297	        if(age > maxAge) {
298	            setDead();
299	        }
300	    }
301	    
302	    /**
303	     * Make this animal's more hungry. This could result in the animal's death.
304	     */
305	    protected void incrementHunger()
306	    {
307	        foodLevel--;
308	        if(foodLevel <= 0) {
309	            setDead();
310	        }
311	    }
312	    
313	    /**
314	     * @Override
315	     * 
316	     * New births will be made into free adjacent locations.
317	     * @param newAnimals A list to return newly born Animals.
318	     */
319	    protected void populate(List<LivingOrganism> newAnimals)
320	    {
321	        Field field = getField();
322	        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Animal.class);
323	        int births = breed();
324	        for(int b = 0; b < births && !free.isEmpty(); b++)
325	        {
326	            newAnimals.add(createNewOffspring(free, infected, immune));
327	        }
328	    }
329	
330	    /**
331	     * Remove a free location from the list, apply disease-inheritance logic,
332	     * and delegate actual instantiation to {@link #createOffspringAt}.
333	     */
334	    protected Animal createNewOffspring(List<Location> free, boolean motherIsInfected, boolean motherIsImmune)
335	    {
336	        Location loc = free.remove(0);
337	
338	        boolean offspringIsInfected = motherIsInfected;
339	        boolean offspringIsImmune = motherIsImmune;
340	
341	        // Infected-but-not-immune mother: small chance offspring gains immunity instead
342	        if (!motherIsImmune && motherIsInfected && rand.nextDouble() < 0.15)
343	        {
344	            offspringIsImmune = true;
345	            offspringIsInfected = false;
346	        }
347	        // Immune mother: most offspring do not inherit immunity
348	        else if (motherIsImmune && rand.nextDouble() < 0.9)
349	        {
350	            offspringIsImmune = false;
351	        }
352	
353	        return createOffspringAt(loc, offspringIsInfected, offspringIsImmune);
354	    }
355	    
356	    /**
357	     * Generate a number representing the number of births,
358	     * if it can breed.
359	     * 
360	     * @return The number of births (may be zero).
361	     */
362	    protected int breed()
363	    {
364	        int births = 0;
365	        Field field = getField();
366	        for(Location where : field.adjacentLocations(getLocation()))
367	        {
368	            Animal neighbor = (Animal) field.getObjectAt(where, Animal.class);
369	            if(neighbor != null && getClass().equals(neighbor.getClass()) && !neighbor.getIsFemale())
370	            {
371	                births = rand.nextInt(maxLitterSize) + 1;
372	            }
373	        }
374	        return births;
375	    }
376	
377	    /**
378	     * An Animal can breed if it has reached the breeding age.
379	     * 
380	     * @return true if the Animal can breed, false otherwise.
381	     */
382	    protected boolean canBreed()
383	    {
384	        return age >= breedingAge;
385	    }
386	    
387	    /**
388	     * @return Returns the status of the animal being infected or not
389	     */
390	    public boolean getIsInfected() 
391	    {
392	        return infected;
393	    }
394	    
395	    /**
396	     * @return Returns the status of the animal being immune or not
397	     */
398	    public boolean getIsImmune() 
399	    {
400	        return immune;
401	    }
402	    
403	    /**
404	     * Checks all the surroundings to see if there any animals which are infected.
405	     * 
406	     * @return Returns true if there is a surrounding animal which is infected.
407	     */
408	    protected boolean surroundingsInfected()
409	    {
410	        Field field = getField();
411	        for(Location where : field.adjacentLocations(getLocation()))
412	        {
413	            Animal neighbor = (Animal) field.getObjectAt(where, Animal.class);
414	            if(neighbor != null && neighbor.getIsInfected())
415	            {
416	                return true;
417	            }
418	        }
419	        return false;
420	    }
421	}

1	import java.util.List;
2	
3	/**
4	 * A class representing the shared characteristics between predators
5	 *
6	 * @version 25/02/2022
7	 */
8	public abstract class Predator extends Animal
9	{
10	    // The likelihood of the predator catching its prey
11	    protected double preyCatchingProbability;
12	
13	    /**
14	     * Create a new predator at location in field.
15	     *
16	     * @param field      The field currently occupied.
17	     * @param location   The location within the field.
18	     * @param isInfected Initial state if the predator is infected or not.
19	     * @param isImmune   Initial state if the predator is immune or not.
20	     */
21	    protected Predator(Field field, Location location, boolean isInfected, boolean isImmune)
22	    {
23	        super(field, location, isInfected, isImmune);
24	        movementProbability = 0.8;
25	    }
26	
27	    /**
28	     * @Override
29	     *
30	     * Predators are less active at night and in fog; otherwise delegates to Animal.act().
31	     *
32	     * @param newPredators A list to receive newly born predators.
33	     */
34	    public void act(List<LivingOrganism> newPredators)
35	    {
36	        if(Time.isNight() && rand.nextDouble() > 0.25)
37	        {
38	            return;
39	        }
40	
41	        if(Weather.getWeather() == Weather.WeatherType.Foggy && rand.nextDouble() > 0.50)
42	        {
43	            return;
44	        }
45	
46	        super.act(newPredators);
47	    }
48	
49	    /**
50	     * @Override
51	     *
52	     * Look for prey adjacent to the current location.
53	     * Eats prey until full. May contract the prey's disease when eating.
54	     *
55	     * @return Where food was found, or null if it wasn't.
56	     */
57	    protected Location findFood()
58	    {
59	        Field field = getField();
60	        for(Location where : field.adjacentLocations(getLocation()))
61	        {
62	            Object animal = field.getObjectAt(where, Animal.class);
63	
64	            if(animal instanceof Prey)
65	            {
66	                Prey prey = (Prey) animal;
67	                if(prey.isAlive() && foodLevel < maxFoodLevel && rand.nextDouble() < preyCatchingProbability)
68	                {
69	                    foodLevel += prey.beEaten();
70	
71	                    if(prey.getIsInfected() && !immune && rand.nextDouble() <= diseaseSpreadProbability)
72	                    {
73	                        infected = true;
74	                    }
75	
76	                    return where;
77	                }
78	            }
79	        }
80	
81	        return null;
82	    }
83	}
