1	import java.util.List;
2	import java.util.Iterator;
3	
4	/**
5	 * A class representing the shared characteristics between Prey
6	 *
7	 * @version 26/02/2022
8	 */
9	public abstract class Prey extends Animal
10	{
11	    /**
12	     * Create a new prey at location in field.
13	     * 
14	     * @param field The field currently occupied.
15	     * @param location The location within the field.
16	     * @param infected Intial state if the prey is infected or not
17	     * @param immmune Intial state if the prey is immune or not
18	     */
19	    protected Prey(Field field, Location location, boolean infected, boolean immune)
20	    {
21	        super(field, location, infected, immune);
22	        movementProbability = 0.75;
23	    }
24	
25	    /**
26	     * @Override
27	     * 
28	     * This is what the prey does most of the time - it may move around, it eats plants, 
29	     * it may breed, it may get infected with a disease, it may become immune to that disease, 
30	     * it may die of the disease, it may die of hunger, and it may die of old age.
31	     * 
32	     * @param newPrey A list to return newly born prey.
33	     */
34	    public void act(List<LivingOrganism> newPrey)
35	    {
36	        // Prey sleep at night
37	        if(Time.isNight()) 
38	        {
39	            return;
40	        }
41	        
42	        super.act(newPrey);
43	    }
44	
45	    /**
46	     * @Override
47	     * 
48	     * Look for plants adjacent to the current location.
49	     * Eats plants till full.
50	     * 
51	     * @return Where food was found, or null if it wasn't.
52	     */
53	    protected Location findFood()
54	    {
55	        Field field = getField();
56	        List<Location> adjacent = field.adjacentLocations(getLocation());
57	        Iterator<Location> it = adjacent.iterator();
58	        
59	        while(it.hasNext()) 
60	        {
61	            Location where = it.next();
62	            
63	            // Get the plant and animal currently at this new location.
64	            Plant plant = (Plant) field.getObjectAt(where, Plant.class);
65	            Animal animal = (Animal) field.getObjectAt(where, Animal.class);
66	            
67	            if(animal == null)
68	            {
69	                if(plant != null)
70	                {
71	                    if(plant.isAlive() && foodLevel < maxFoodLevel)
72	                    { 
73	                        // Prey is hungry and plant is availiable so eat
74	                        // the plant.
75	                        int plantFoodValue = plant.beEaten();
76	                        foodLevel += plantFoodValue;
77	                        
78	                        return where;
79	                    }
80	                }
81	            }
82	        }
83	        
84	        return null;
85	    }
86	}
