1	import java.util.List;
2	
3	/**
4	 * Plants grow over time, can be partially eaten, spread to adjacent empty cells
5	 * (at a rate that varies by weather), and die if eaten below zero health.
6	 *
7	 * @version 26/02/2022
8	 */
9	public class Plant extends LivingOrganism
10	{
11	    // its current health percentage
12	    private double healthPercentage;
13	    // The likelihood a plants being able to spread into areas with no plants
14	    private double spreadProbability;
15	    // The rate at which plants grow back and increase their health percentage
16	    private static final double GROWTH_RATE = 0.05;
17	    // The amount of health percentage which is taken away every time an animal eats a plant
18	    private static final double PERCENTAGE_EATEN = 0.52;
19	    // The food value of itself - how much the hunter's food level increases when eating it.
20	    private static final int FOOD_VALUE = 3;
21	    
22	    /**
23	     * Create a new PLANT at location in field.
24	     * 
25	     * @param randomHealthPercentage If true, the plant will have a random age.
26	     * @param field The field currently occupied.
27	     * @param location The location within the field.
28	     */
29	    public Plant(boolean randomHealthPercentage, Field field, Location location) 
30	    {
31	        super(field, location);
32	        
33	        foodValue = FOOD_VALUE;
34	        
35	        healthPercentage = 1;
36	        if (randomHealthPercentage) 
37	        {
38	            healthPercentage = rand.nextDouble();
39	            
40	            if (healthPercentage < 0.1)
41	            {
42	                healthPercentage = 0.1;
43	            }
44	        }
45	    }
46	    
47	    /**
48	     * @Override
49	     * 
50	     * This is what the plants does most of the time - it runs 
51	     * around. Sometimes it will breed or die of old age.
52	     * 
53	     * @param newPlants A list to return new Plants.
54	     */
55	    public void act(List<LivingOrganism> newPlants)
56	    {
57	        incrementAge();
58	        if(!Time.isNight()) 
59	        {
60	            if(isAlive()) 
61	            {
62	                switch (Weather.getWeather())
63	                {
64	                    case Sunny:
65	                        spreadProbability = 0.2;
66	                        break;
67	                    case Rainy:
68	                        spreadProbability = 0.14;
69	                        break;
70	                    case Foggy:
71	                        spreadProbability = 0.05;
72	                        break;
73	                    case Cloudy:
74	                        spreadProbability = 0.1;
75	                        break;
76	                    case Clear:
77	                        spreadProbability = 0.08;
78	                        break;
79	                }    
80	                
81	                if (rand.nextDouble() < spreadProbability) 
82	                {
83	                    populate(newPlants);
84	                }
85	            }
86	        }
87	    }
88	    
89	    /**
90	     * When called, the plant gets eaten and loses a
91	     * pre-defined amount of health.
92	     */
93	    protected int beEaten() 
94	    {
95	        healthPercentage -= PERCENTAGE_EATEN;
96	        if (healthPercentage <= 0)
97	        {
98	            setDead();
99	        }
100	        
101	        return foodValue;
102	    }
103	    
104	    /**
105	     * @Override
106	     *
107	     * Makes the plant grow to full health.
108	     */
109	    protected void incrementAge() 
110	    {
111	        healthPercentage += GROWTH_RATE;
112	        if (healthPercentage > 1.0) 
113	        {
114	            healthPercentage = 1.0;
115	        }
116	    }
117	
118	    /**
119	     * @Override
120	     * 
121	     * Indicate that the animal is no longer alive.
122	     * It is removed from the field.
123	     */
124	    protected void setDead()
125	    {
126	        alive = false;
127	        if(location != null) 
128	        {
129	            field.clear(location, Plant.class);
130	            location = null;
131	        }
132	    }
133	    
134	    /**
135	     * @Override
136	     * 
137	     * Place the plant at the new location in the given field.
138	     * 
139	     * @param newLocation The plant's new location.
140	     */
141	    protected void setLocation(Location newLocation)
142	    {
143	        if(location != null) 
144	        {
145	            field.clear(location, Plant.class);
146	        }
147	        
148	        location = newLocation;
149	        field.place(this, newLocation);
150	    }
151	    
152	    /**
153	     * @Override
154	     * 
155	     * Check whether or not this Plant is to give birth at this step.
156	     * New births will be made into free adjacent locations.
157	     * 
158	     * @param newPlants A list to return newly born Plants.
159	     */
160	    protected void populate(List<LivingOrganism> newPlants)
161	    {
162	        // Get a list of adjacent free locations.
163	        Field field = getField();
164	        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Plant.class);
165	        
166	        // New plants are spread into adjacent locations.
167	        while (!free.isEmpty())
168	        {
169	            newPlants.add(createOffspring(free));
170	        }
171	    }
172	    
173	    private Plant createOffspring(List<Location> free)
174	    {
175	        return new Plant(false, field, free.remove(0));
176	    }
177	}
