1	/**
2	 * A simple model of a lion.
3	 * lions age, move, breed, eat prey, and die.
4	 *
5	 * @version 25/02/2022
6	 */
7	public class Lion extends Predator
8	{
9	    public static final double PREY_CATCHING_PROBABILITY = 0.80;
10	    public static final int BREEDING_AGE = 80;
11	    public static final int MAX_AGE = 1400;
12	    public static final double BREEDING_PROBABILITY = 0.65;
