1	import java.util.Random;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Iterator;
5	import java.awt.Color;
6	import javax.swing.JButton;
7	
8	/**
9	 * A simple predator-prey simulator, based on a rectangular field
10	 * containing rabbits and foxes.
11	 *
12	 * @version 26/02/2022
13	 */
14	public class Simulator
15	{
16	    // Field dimensions.
17	    private static final int DEFAULT_WIDTH = 270;
18	    private static final int DEFAULT_DEPTH = 180;
19	
20	    // Initial population probabilities per grid cell.
21	    private static final double LION_CREATION_PROBABILITY    = 0.0125;
22	    private static final double CHEETAH_CREATION_PROBABILITY = 0.0125;
23	    private static final double ZEBRA_CREATION_PROBABILITY   = 0.08;
24	    private static final double GIRAFFE_CREATION_PROBABILITY = 0.08;
25	    private static final double LEMUR_CREATION_PROBABILITY   = 0.081;
26	
27	    // Named indices into the buttons array.
28	    private static final int BTN_PLAY_PAUSE = 0;
29	    private static final int BTN_RUN_LONG   = 1;
30	    private static final int BTN_STEP       = 2;
31	    private static final int BTN_RESET      = 3;
32	    private static final int BTN_QUIT       = 4;
33	
34	    // List of animals in the field.
35	    private List<LivingOrganism> animals;
36	    // List of plants in the field
37	    private List<LivingOrganism> plants;
38	    // The current state of the field.
39	    private Field field;
40	    // A graphical view of the simulation.
41	    private SimulatorView view;
42	    // List of buttons that are used to control the simulation.
43	    private JButton[] buttons;
44	    
45	    /**
46	     * Construct a simulation field with default size.
47	     */
48	    public Simulator()
49	    {
50	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
51	    }
52	    
53	    /**
54	     * Create a simulation field with the given size.
55	     * @param depth Depth of the field. Must be greater than zero.
56	     * @param width Width of the field. Must be greater than zero.
57	     */
58	    public Simulator(int depth, int width)
59	    {
60	        if(width <= 0 || depth <= 0) {
61	            System.out.println("The dimensions must be greater than zero.");
62	            System.out.println("Using default values.");
63	            depth = DEFAULT_DEPTH;
64	            width = DEFAULT_WIDTH;
65	        }
66	        
67	        animals = new ArrayList<>();
68	        plants = new ArrayList<>();
69	        field = new Field(depth, width);
70	        buttons = new JButton[5];
71	
72	        JButton playPause = new JButton("Play");
73	        playPause.addActionListener(e -> new Thread(() -> playPauseButton()).start());
74	        buttons[BTN_PLAY_PAUSE] = playPause;
75	
76	        JButton runLongSim = new JButton("Run Long Sim");
77	        runLongSim.addActionListener(e -> new Thread(() -> runLongSimulation()).start());
78	        buttons[BTN_RUN_LONG] = runLongSim;
79	
80	        JButton simOneStep = new JButton("Sim One Step");
81	        simOneStep.addActionListener(e -> simulateOneStep());
82	        buttons[BTN_STEP] = simOneStep;
83	
84	        JButton reset = new JButton("Reset");
85	        reset.addActionListener(e -> reset());
86	        buttons[BTN_RESET] = reset;
87	
88	        JButton quit = new JButton("Quit");
89	        quit.addActionListener(e -> quit());
90	        buttons[BTN_QUIT] = quit;
91	        
92	        // Sets the visibility of the buttons in accordance to the current state of the simulation.
93	        buttonToggle();
94	
95	        // Create a view of the state of each location in the field.
96	        view = new SimulatorView(depth, width, buttons);
97	        view.setColor(Zebra.class, Color.BLACK, Color.WHITE);
98	        view.setColor(Giraffe.class, Color.YELLOW, Color.BLACK);
99	        view.setColor(Lemur.class, Color.BLUE, Color.WHITE);
100	        view.setColor(Lion.class, Color.RED, Color.WHITE);
101	        view.setColor(Cheetah.class, Color.ORANGE, Color.BLACK);
102	        view.setColor(Plant.class, Color.GREEN, Color.BLACK);
103	        
104	        // Setup a valid starting point.
105	        reset();
106	    }
107	    
108	    /**
109	     * Controls the functionality of the Play/Pause button. This depends
110	     * on whether the simulation is paused or not.
111	     */
112	    private void playPauseButton() 
113	    {
114	        boolean isPaused = Time.getIsPaused();
115	        
116	        Time.toggleIsPaused();
117	        
118	        if (isPaused) {
119	            if (! Time.getIsFinished()) {
120	                simulate();
121	            }
122	        }
123	        
124	        buttonToggle();
125	    }
126	    
127	    /**
128	     * Run the simulation from its current state for a reasonably long 
129	     * period: 500 steps.
130	     */
131	    private void runLongSimulation()
132	    {
133	        simulate(500);
134	    }
135	    
136	    /**
137	     * Run the simulation from its current state for the given number of 
138	     * steps.
139	     * @param numSteps The number of steps to run for.
140	     */
141	    private void simulate(int numSteps)
142	    {
143	        // Sets the number of steps that the simulation run started at
144	        Time.setStepsToRunFor(numSteps);
145	        simulate();
146	    }
147	    
148	    /**
149	     * Run the simulation from its current state for the given number of 
150	     * steps in the Time Class.
151	     * Stop before the given number of steps if it ceases to be viable.
152	     * This is considered to be when only one species remains.
153	     */
154	    private void simulate() 
155	    {
156	        Time.setIsPaused(false);
157	        
158	        // Adjust button visibility.
159	        buttonToggle();
160	        
161	        while (! Time.getIsPaused() && ! Time.getIsFinished() && view.isViable(field)) {
162	            simulateOneStep();
163	        }
164	        
165	        Time.setIsPaused(true);
166	        buttonToggle();
167	    }
168	    
169	    /**
170	     * Run the simulation from its current state for a single step.
171	     * Iterate over the whole field updating the state of each
172	     * predator, prey, and plant.
173	     */
174	    private void simulateOneStep()
175	    {
176	        Time.incrementStep();
177	        Weather.updateWeather();
178	
179	        // Provide space for newborn animals and plants;
180	        List<LivingOrganism> newAnimals = new ArrayList<>();
181	        List<LivingOrganism> newPlants = new ArrayList<>();
182	        
183	        // Let all animals act.
184	        for(Iterator<LivingOrganism> it = animals.iterator(); it.hasNext(); )
185	        {
186	            Animal animal = (Animal) it.next();
187	            animal.act(newAnimals);
188	            if(!animal.isAlive())
189	            {
190	                it.remove();
191	            }
192	        }
193	
194	        // Let all plants act.
195	        for(Iterator<LivingOrganism> it = plants.iterator(); it.hasNext(); )
196	        {
197	            Plant plant = (Plant) it.next();
198	            plant.act(newPlants);
199	            if(!plant.isAlive())
200	            {
201	                it.remove();
202	            }
203	        }
204	        
205	        // Add the newly born animals and plants to the main lists.
206	        animals.addAll(newAnimals);
207	        plants.addAll(newPlants); 
208	
209	        // Show the current state in the view.
210	        view.showStatus(field);
211	    }
212	        
213	    /**
214	     * Reset the simulation to a starting position.
215	     */
216	    private void reset()
217	    {
218	        // Resets the visibility of the buttons and resets the step number
219	        Time.resetStep();
220	        buttonToggle();
221	        
222	        // Clears all current animals and plants then repopulates the area
223	        animals.clear();
224	        plants.clear();
225	        populate();
226	        
227	        // Show the starting state in the view.
228	        view.showStatus(field);
229	    }
230	    
231	    /**
232	     * Randomly populate the field with predators, prey, and plants.
233	     */
234	    private void populate()
235	    {
236	        Random rand = Randomizer.getRandom();
237	        field.clear();
238	        for(int row = 0; row < field.getDepth(); row++) 
239	        {
240	            for(int col = 0; col < field.getWidth(); col++) 
241	            {
242	                //plants will fill the entire field initially.
243	                Location location = new Location(row, col);
244	                Plant plant = new Plant(true, field, location);
245	                plants.add(plant);
246	                
247	                Animal animal = null;
248	
249	                if(rand.nextDouble() <= LION_CREATION_PROBABILITY)
250	                {
251	                    animal = new Lion(true, field, location, false, false);
252	                }
253	                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY)
254	                {
255	                    animal = new Cheetah(true, field, location, false, false);
256	                }
257	                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY)
258	                {
259	                    animal = new Zebra(true, field, location, false, false);
260	                }
261	                else if(rand.nextDouble() <= GIRAFFE_CREATION_PROBABILITY)
262	                {
263	                    animal = new Giraffe(true, field, location, false, false);
264	                }
265	                else if(rand.nextDouble() <= LEMUR_CREATION_PROBABILITY)
266	                {
267	                    animal = new Lemur(true, field, location, false, false);
268	                }
269	                
270	                if(animal != null) 
271	                {
272	                    animals.add(animal);
273	                }
274	            }
275	        }
276	    }
277	    
278	    /**
279	     * Sets the visibility of the buttons in accordance with the current
280	     * state of the simulation.
281	     */
282	    private void buttonToggle()
283	    {
284	        boolean isFinished = Time.getIsFinished();
285	        boolean isStopped = Time.getIsPaused() || isFinished;
286	
287	        buttons[BTN_PLAY_PAUSE].setEnabled(!isFinished);
288	        buttons[BTN_RUN_LONG].setEnabled(isStopped);
289	        buttons[BTN_STEP].setEnabled(isStopped);
290	        buttons[BTN_RESET].setEnabled(isStopped);
291	
292	        buttons[BTN_PLAY_PAUSE].setText(isStopped ? "Play" : "Pause");
293	    }
294	    
295	    /**
296	     * Used by the quit button to close the application.
297	     */
298	    private void quit()
299	    {
300	        System.exit(0);
301	    }
302	}
