301	    /**
302	     * Provide a graphical view of a rectangular field. This is 
303	     * a nested class (a class defined inside a class) which
304	     * defines a custom component for the user interface. This
305	     * component displays the field.
306	     */
307	    private class FieldView extends JPanel
308	    {
309	        private final int GRID_VIEW_SCALING_FACTOR = 6;
310	
311	        private int gridWidth, gridHeight;
312	        private double xScale, yScale;
313	        Dimension size;
314	        private Graphics g;
315	        private Image fieldImage;
316	
317	        /**
318	         * Create a new FieldView component.
319	         */
320	        public FieldView(int height, int width)
321	        {
322	            gridHeight = height;
323	            gridWidth = width;
324	            size = new Dimension(0, 0);
325	        }
326	
327	        /**
328	         * Tell the GUI manager how big we would like to be.
329	         * 
330	         * @return Dimensions
331	         */
332	        public Dimension getPreferredSize()
333	        {
334	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
335	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
336	        }
337	
338	        /**
339	         * Prepare for a new round of painting. Since the component
340	         * may be resized, compute the scaling factor again.
341	         */
342	        public void preparePaint()
343	        {
344	            if(! size.equals(getSize())) {  // if the size has changed...
345	                size = getSize();
346	                fieldImage = fieldView.createImage(size.width, size.height);
347	                g = fieldImage.getGraphics();
348	            
349	                xScale = size.width / gridWidth;
350	                if(xScale < 1) {
351	                    xScale = GRID_VIEW_SCALING_FACTOR;
352	                }
353	                yScale = size.height / gridHeight;
354	                if(yScale < 1) {
355	                    yScale = GRID_VIEW_SCALING_FACTOR;
356	                }
357	                
358	                // Makes sure that the grid remains in proportion
359	                // (the grid squares remain as squares)
360	                if(xScale > yScale) {
361	                    xScale = yScale;
362	                }
363	                else if(xScale < yScale) {
364	                    yScale = xScale;
365	                }
366	            }
367	        }
368	        
369	        /**
370	         * Paint on grid location on this field in a given color.
371	
372	         * @param x X-position to draw the mark
373	         * @param y Y-position to draw the mark
374	         * @param color The colour to draw the mark
375	         */
376	        private void drawMark(int x, int y, Color color)
377	        {
378	            g.setColor(color);
379	            g.fillRect((int)(x * xScale), (int)(y * yScale) , (int)(xScale - 1.0), (int)(yScale - 1.0));
380	        }
381	
382	        /**
383	         * The field view component needs to be redisplayed. Copy the
384	         * internal image to screen.
385	         * 
386	         * @param g Graphics
387	         */
388	        public void paintComponent(Graphics g)
389	        {
390	            if(fieldImage != null) 
391	            {
392	                Dimension currentSize = getSize();
393	                
394	                if(size.equals(currentSize)) 
395	                {
396	                    g.drawImage(fieldImage, 0, 0, null);
397	                }
398	                else 
399	                {
400	                    // Rescale the previous image.
401	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
402	                }
403	            }
404	        }
405	    }
406	}
