3	/**
4	 * This class collects and provides some statistical data on the state 
5	 * of a field. It is flexible: it will create and maintain a counter 
6	 * for any class of object that is found within the field.
7	 *
8	 * @version 26/02/2022
9	 */
10	public class FieldStats
11	{
12	    // Counters for each type of entity (lion, zebra, etc.) in the simulation.
13	    private HashMap<Class<?>, Counter> counters;
14	    // Whether the counters are currently up to date.
15	    private boolean countsValid;
16	
17	    /**
18	     * Construct a FieldStats object.
19	     */
20	    public FieldStats()
21	    {
22	        // Set up a collection for counters for each type of animal that
23	        // we might find
24	        counters = new HashMap<>();
25	        countsValid = true;
26	    }
27	
28	    /**
29	     * Get details of what is in the field.
30	     * 
31	     * @param field The field to get the population details of.
32	     * 
33	     * @return A string describing what is in the field.
34	     */
35	    public String getPopulationDetails(Field field)
36	    {
37	        StringBuilder buffer = new StringBuilder();
38	        if(!countsValid) {
39	            generateCounts(field);
40	        }
41	        for(Counter info : counters.values()) {
42	            buffer.append(info.getName());
43	            buffer.append(": ");
44	            buffer.append(info.getCount());
45	            buffer.append(' ');
46	        }
47	        return buffer.toString();
48	    }
49	    
50	    /**
51	     * Invalidate the current set of statistics; reset all 
52	     * counts to zero.
53	     */
54	    public void reset()
55	    {
56	        countsValid = false;
57	        for(Counter count : counters.values()) {
58	            count.reset();
59	        }
60	    }
61	
62	    /**
63	     * Increment the count for one object.
64	     * 
65	     * @param objectType The class of animal to increment.
66	     */
67	    public void incrementCount(Class<?> objectType)
68	    {
69	        Counter count = counters.get(objectType);
70	        if(count == null) {
71	            count = new Counter(objectType.getName());
72	            counters.put(objectType, count);
73	        }
74	        count.increment();
75	    }
76	
77	    /**
78	     * Indicate that an animal count has been completed.
79	     */
80	    public void countFinished()
81	    {
82	        countsValid = true;
83	    }
84	
85	    /**
86	     * Determine whether the simulation is still viable.
87	     * I.e., should it continue to run.
88	     * 
89	     * @return true If there is more than one species alive.
90	     */
91	    public boolean isViable(Field field)
92	    {
93	        // How many counts are non-zero.
94	        int nonZero = 0;
95	        if(!countsValid) 
96	        {
97	            generateCounts(field);
98	        }
99	        
100	        for(Counter info : counters.values())
101	        {
102	            if(info.getCount() > 0)
103	            {
104	                nonZero++;
105	            }
106	        }
107	        return nonZero > 1;
108	    }
109	    
110	    /**
111	     * Generate counts of the number of all species of 
112	     * animal and plant.
113	     * These are not kept up to date as animals and plants
114	     * are placed in the field, but only when a request
115	     * is made for the information.
116	     * 
117	     * @param field The field to generate the stats for.
118	     */
119	    private void generateCounts(Field field)
120	    {
121	        reset();
122	        for(int row = 0; row < field.getDepth(); row++) 
123	        {
124	            for(int col = 0; col < field.getWidth(); col++) 
125	            {
126	                Object object = field.getObjectAt(row, col, Animal.class);
127	                
128	                if(object != null) 
129	                {
130	                    incrementCount(object.getClass());
131	                }
132	            }
133	        }
134	        
135	        countsValid = true;
136	    }
137	}
